import heapq

def top_k(values, k):
    if k < 0 or k > len(values):
        raise ValueError("k out of range")
    if k == 0:
        return []
    candidates = []
    for value in values:
        if len(candidates) < k:
            heapq.heappush(candidates, value)
        elif value > candidates[0]:
            heapq.heapreplace(candidates, value)
    return sorted(candidates, reverse=True)

values = [5, 1, 5, 3]
print(top_k(values, 2))
print(top_k(values, 0))
print(top_k(values, len(values)))
print(top_k([], 0))
print(values)

import heapq

def top_k(values, k):
