import heapq

def smallest_k(values, k):
    if k < 0 or k > len(values):
        raise ValueError("k out of range")
    if k == 0:
        return []
    heap = list(values)
    heapq.heapify(heap)
    result = []
    for _ in range(k):
        result.append(heapq.heappop(heap))
    return result

print(smallest_k([4, 1, 1, 3], 3))
print(smallest_k([2, -1], 2))
print(smallest_k([], 0))
try:
    smallest_k([2], -1)
except ValueError:
    print("ValueError")

import heapq

def kth_largest(values, k):
    if k < 1 or k > len(values):
        raise ValueError("k out of range")
    heap = []
    for value in values:
        if len(heap) < k:
            heapq.heappush(heap, value)
        elif value > heap[0]:
            heapq.heapreplace(heap, value)
    return heap[0]

print(kth_largest([5, 1, 5, 3], 2))
print(kth_largest([5, 1, 5, 3], 4))
print(kth_largest([8], 1))
try:
    kth_largest([], 0)
except ValueError:
    print("ValueError")

import heapq

def top_k_indices(values, k):
    if k < 0 or k > len(values):
        raise ValueError("k out of range")
    if k == 0:
        return []
    heap = [(-value, index) for index, value in enumerate(values)]
    heapq.heapify(heap)
    result = []
    for _ in range(k):
        negative_value, index = heapq.heappop(heap)
        result.append(index)
    return result

print(top_k_indices([7, 9, 9, 4], 2))
print(top_k_indices([7, 9, 9, 4], 4))
print(top_k_indices([], 0))
